  [ [[v5748eaic9nc1]] ] = { t = [[改变外形的持续时间]], q = [[拥有改变外形能力的生物，是否使用改变外形法术的持续时间，并且必须在持续时间到期时不断重新施展？]], a = [[按最初的写法，依照开拓者规则中改变外形的运作方式，拥有该能力的生物必须每隔几分钟就重新使用一次，因为它基于一个有持续时间的法术。这对变形怪这类长时间以另一种形态生活的生物很不利：重新启动这项能力会毁掉它们的伪装，尤其是它睡着的时候根本无法这样做。

