  [ [[v5748eaic9nsz]] ] = { t = [[攫抓的体型限制]], q = [[《怪物图鉴》的攫抓规则说该能力只对比怪物体型小的生物起作用，但《怪物图鉴 2》的攫抓规则说该能力对不超过怪物自身体型的生物起作用。哪个是对的？]], a = [[《怪物图鉴 2》是新的更新版本：攫抓对体型不超过拥有攫抓能力的怪物的生物起作用。下次重印最初的《怪物图鉴》时，我们会更新所有关于攫抓及类似能力的引用，以反映这一改动。]], book = [[怪物图鉴]], date = [[2011/01/03]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fo#v5748eaic9nsz]], cat = [[FAQ]], ai = true, pages = { [[攫抓(怪物能力)]] } },
