  [ [[v5748eaic9rdk]] ] = { t = [[爪抓与爪击的位置]], q = [[如果我获得了爪抓攻击，可以把这些爪抓攻击放在脚上吗？]], a = [[如果你是两足生物（大致是类人体型，有两条手臂和两条腿），你的爪抓必须长在手上；不能把它们分配给任何其他肢体或身体部位。

如果你是四足生物（或有四条以上的腿），你可以在脚上长爪抓。如果你所有的脚上都有爪抓，通常你无法在自己的回合里使用全部这些爪抓攻击，除非你拥有猛扑或耙抓之类的特殊能力。

爪击与爪抓相似，但长在生物的脚上，通常是两足生物（尤其是巨鹰或鹰身女妖这类会飞的两足生物）。赋予你爪抓攻击的能力，不能当作爪击攻击来使用（换句话说，你不能为了把它用在另一个肢体上，就给这项能力的游戏机制“换皮”）。]], book = [[怪物图鉴]], date = [[2013/01/11]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fo#v5748eaic9rdk]], cat = [[FAQ]], ai = true, pages = { [[天生武器]] } },
  [ [[v5748eaic9oyk]] ] = { t = [[负能量亲和]], q = [[负能量亲和这项能力（《怪物图鉴 2》第 299 页）应当如何运作？]], a = [[这项能力的本意是：该生物被负能量治愈（如同不死生物），被正能量伤害（如同不死生物）；这是自动发生的，与目标或施放能量者的意图无关。然而，按原文写法，由于“反应”一词没有明确的定义，这项能力有些令人困惑。这项能力将在《怪物图鉴 2》下次印刷时修改。

更新：第 299 页——在负能量亲和能力的描述中，将现有条目替换为下面的内容：

负能量亲和（Ex）该生物是活着的，但对于一切对不死生物与对生物影响不同的效果，例如治疗法术和引导能量，都视其为不死生物。格式：负能量亲和；位置：防御能力。]], book = [[怪物图鉴]], date = [[2012/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fo#v5748eaic9oyk]], cat = [[FAQ]], ai = true, pages = { [[负能量亲和]] } },
  [ [[v5748eaic9p05]] ] = { t = [[猛扑与迭代攻击]], q = [[如果我拥有这项能力（第 302 页），我能在全力攻击中进行带武器的迭代攻击吗？]], a = [=[任何你能作为全力攻击进行的近战攻击序列，都允许作为冲锋—猛扑—全力攻击的一部分。例如，拥有[[高等野兽图腾]]狂暴之力的野蛮人获得猛扑通用怪物能力，可以在她的冲锋—猛扑—全力攻击中，用人造近战武器进行迭代攻击。]=], book = [[怪物图鉴]], date = [[2012/01/02]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fo#v5748eaic9p05]], cat = [[FAQ]], ai = true, pages = { [[猛扑(怪物能力)]], [[高等野兽图腾]] } },
