  [ [[v5748eaic9r4l]] ] = { t = [[猛扑与加速术]], q = [[如果拥有猛扑的生物处于加速术效果下，并且进行了冲锋，它能获得加速术提供的额外攻击吗？]], a = [[可以。

编辑于 9/9/13：这是对加速术如何与那些实质上相当于全力攻击的效果互动的修订裁定，尽管该生物并未明确使用全力攻击动作（加速术要求这一点）。先前的裁定暗示，猛扑不能获得加速术的额外攻击，因为猛扑并未使用全力攻击动作。]], book = [[怪物图鉴]], date = [[2013/01/09]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fo#v5748eaic9r4l]], cat = [[FAQ]], ai = true, pages = { [[猛扑(怪物能力)]], [[加速术]] } },
